from ..interactions import dashboard
from ..interactions import ro_treat

class ROTreat():
    def __init__(self) -> None:
        pass

    def schedule_treatment_for_patient(self, patientLastName: str) -> None:
        dashboard.open_patient_ro_treat(patientLastName)
        ro_treat.open_tx_calendar()
        ro_treat.click_insert_sessions_tab()
        ro_treat.click_insert_sessions_other_radio_button()
        ro_treat.click_insert_sessions_button()
        ro_treat.clear_insert_sessions_dialog()
        ro_treat.click_schedule_all_fields()
        ro_treat.click_fields_to_be_scheduled_single_add_button(2)
        ro_treat.click_fields_to_be_scheduled_ok_button()
        ro_treat.click_schedule_fields_button()